<?php
session_start();
if(empty($_SESSION['user_id'])){header('Location: login.php');exit;}
if(($_SESSION['user_role']??'student')!=='student'){http_response_code(403);exit('Student accounts only.');}
$id=(int)$_SESSION['user_id'];function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$err='';$msg='';$goal=5;$set=array();$days=array();$current=0;$longest=0;$week=0;$today=date('Y-m-d');
try{$db=new PDO('mysql:host=127.0.0.1;port=3306;dbname=kanji_master;charset=utf8mb4','root','root',array(PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC));
$db->exec("CREATE TABLE IF NOT EXISTS student_study_goals(user_id INT PRIMARY KEY,weekly_goal INT NOT NULL DEFAULT 5,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if(empty($_SESSION['goal_csrf']))$_SESSION['goal_csrf']=bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']==='POST'){if(!isset($_POST['csrf_token'])||!hash_equals($_SESSION['goal_csrf'],(string)$_POST['csrf_token']))$err='Security check failed. Refresh and try again.';else{$n=(int)($_POST['weekly_goal']??5);if($n<1||$n>7)$err='Choose 1 to 7 days.';else{$s=$db->prepare('INSERT INTO student_study_goals(user_id,weekly_goal) VALUES(?,?) ON DUPLICATE KEY UPDATE weekly_goal=VALUES(weekly_goal)');$s->execute(array($id,$n));$goal=$n;$msg='Weekly goal saved.';}}}
$s=$db->prepare('SELECT weekly_goal FROM student_study_goals WHERE user_id=?');$s->execute(array($id));$g=$s->fetchColumn();if($g!==false)$goal=(int)$g;
$s=$db->prepare('SELECT DISTINCT DATE(created_at) d FROM practice_attempts WHERE user_id=? ORDER BY d DESC');$s->execute(array($id));foreach($s->fetchAll() as $r){$days[]=$r['d'];$set[$r['d']]=true;}
$ws=date('Y-m-d',strtotime('monday this week'));$we=date('Y-m-d',strtotime('sunday this week'));foreach($days as $d)if($d>=$ws&&$d<=$we)$week++;
$d=isset($set[$today])?$today:date('Y-m-d',strtotime('-1 day'));while(isset($set[$d])){$current++;$d=date('Y-m-d',strtotime($d.' -1 day'));}
$run=0;$prev=null;foreach(array_reverse($days) as $d){$run=$prev===null?1:($d===date('Y-m-d',strtotime($prev.' +1 day'))?$run+1:1);$longest=max($longest,$run);$prev=$d;}
}catch(Throwable $e){error_log('Study streak: '.$e->getMessage());$err=$err?:'Could not load history. Check MAMP/MySQL and save a practice attempt first.';}
$pct=$goal?min(100,(int)round($week/$goal*100)):0;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Study Streak | Kanji Master</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1020;color:#f8fafc;font:15px/1.55 Arial,sans-serif}a{color:#c7d2fe;text-decoration:none}header{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:18px 4%;background:#111827;border-bottom:1px solid #263247}.brand{font-weight:bold}.brand span{color:#a5b4fc}nav{display:flex;gap:8px;flex-wrap:wrap}nav a{padding:8px 10px;border:1px solid #334155;border-radius:9px}main{width:min(950px,94%);margin:30px auto 60px}.muted,.hint,.label{color:#cbd5e1}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px;margin:22px 0}.card,.panel{background:#151d31;border:1px solid #334155;border-radius:16px;padding:20px}.metric{font-size:34px;font-weight:800;margin:8px 0}.label{font-size:13px}.panel{margin-top:16px}.track{height:14px;background:#273449;border-radius:99px;overflow:hidden;margin:14px 0}.fill{height:100%;background:#818cf8}.days{display:grid;grid-template-columns:repeat(7,1fr);gap:7px;margin-top:14px}.day{text-align:center;background:#0f172a;border:1px solid #334155;border-radius:10px;padding:10px 2px;font-size:12px;color:#cbd5e1}.day strong{display:block;color:white;font-size:20px}.done{background:#123b34;border-color:#2c8b70}select,button{padding:10px;border-radius:9px;font:inherit}select{background:#0f172a;color:white;border:1px solid #475569}button{background:#a5b4fc;color:#111827;border:0;font-weight:bold;cursor:pointer}.notice{padding:12px;border-radius:10px;background:#064e3b;margin:12px 0}.err{background:#7f1d1d}.formrow{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:12px}@media(max-width:600px){.card,.panel{padding:15px}.days{gap:3px}.day{font-size:10px}}</style></head><body><header><div class="brand">字 <span>Kanji Master</span> · Study Streak</div><nav><a href="dashboard.php">← Dashboard</a><a href="practice.php">Writing practice</a><a href="study_activity.php">Study activity</a><a href="logout.php">Log out</a></nav></header><main><p class="label">SMALL STEPS EVERY DAY</p><h1>My study streak & weekly goal</h1><p class="muted">A day counts when you save at least one writing-practice attempt.</p><?php if($err):?><div class="notice err"><?=h($err)?></div><?php elseif($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><section class="grid"><div class="card"><div class="label">🔥 Current streak</div><div class="metric"><?=$current?> day<?=$current===1?'':'s'?></div><div class="label"><?=isset($set[$today])?'You practised today!':'Save practice today to keep your streak active.'?></div></div><div class="card"><div class="label">🏆 Longest streak</div><div class="metric"><?=$longest?> day<?=$longest===1?'':'s'?></div><div class="label">Consecutive days in saved history.</div></div><div class="card"><div class="label">📅 This week</div><div class="metric"><?=$week?> / <?=$goal?></div><div class="label">Days with saved practice this week.</div></div></section><section class="panel"><h2>Weekly goal progress · <?=$pct?>%</h2><div class="track"><div class="fill" style="width:<?=$pct?>%"></div></div><p class="hint"><?=$week>=$goal?'Goal reached! Great work.':'You need '.max(0,$goal-$week).' more practice day'.(max(0,$goal-$week)===1?'':'s').' to reach your goal.'?></p><form method="post" class="formrow"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['goal_csrf']??'')?>"><label for="weekly_goal">Goal per week:</label><select id="weekly_goal" name="weekly_goal"><?php for($i=1;$i<=7;$i++):?><option value="<?=$i?>" <?=$goal===$i?'selected':''?>><?=$i?> day<?=$i===1?'':'s'?></option><?php endfor;?></select><button type="submit">Save goal</button></form><p class="hint">The goal counts distinct days, not total attempts.</p></section><section class="panel"><h2>This week's activity</h2><p class="hint">Monday to Sunday.</p><div class="days"><?php $m=strtotime('monday this week');$labels=array('Mon','Tue','Wed','Thu','Fri','Sat','Sun');for($i=0;$i<7;$i++):$d=date('Y-m-d',strtotime('+'.$i.' days',$m));$done=isset($set[$d]);?><div class="day <?=$done?'done':''?>"><?=h($labels[$i])?><strong><?=$done?'✓':'—'?></strong><?=h(date('M j',strtotime($d)))?></div><?php endfor;?></div></section><p class="hint">Only saved writing-practice history is counted. The app may retain only the latest 100 attempts, so older streaks may be incomplete.</p></main></body></html>